// NewChatPayload builds a assistant service chat endpoint payload.
func NewChatPayload(body *ChatRequestBody, cookie string) *assistant.ChatPayload {
	v := &assistant.ChatPayload{}
	v.Messages = make([]*assistant.AssistantMessage, len(body.Messages))
	for i, val := range body.Messages {
		if val == nil {
			v.Messages[i] = nil
			continue
		}
		v.Messages[i] = unmarshalAssistantMessageRequestBodyToAssistantAssistantMessage(val)
	}
	if body.Tools != nil {
		v.Tools = make([]*assistant.AssistantTool, len(body.Tools))
		for i, val := range body.Tools {
			if val == nil {
				v.Tools[i] = nil
				continue
			}
			v.Tools[i] = unmarshalAssistantToolRequestBodyToAssistantAssistantTool(val)
		}
	}
	v.Cookie = cookie

	return v
}

// NewAgentPayload builds a assistant service agent endpoint payload.
func NewAgentPayload(body *AgentRequestBody, cookie string) *assistant.AgentPayload {
	v := &assistant.AgentPayload{
		Question:    *body.Question,
		SessionID:   body.SessionID,
		RunID:       body.RunID,
		ResumeToken: body.ResumeToken,
		ToolCallID:  body.ToolCallID,
		ToolResult:  body.ToolResult,
	}
	if body.Page != nil {
		v.Page = unmarshalAIPageRequestBodyToAssistantAIPage(body.Page)
	}
	if body.Tools != nil {
		v.Tools = make([]*assistant.AssistantTool, len(body.Tools))
		for i, val := range body.Tools {
			if val == nil {
				v.Tools[i] = nil
				continue
			}
			v.Tools[i] = unmarshalAssistantToolRequestBodyToAssistantAssistantTool(val)
		}
	}
	v.Cookie = cookie

	return v
}

