// ValidateChatRequestBody runs the validations defined on ChatRequestBody
func ValidateChatRequestBody(body *ChatRequestBody) (err error) {
	if body.Messages == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("messages", "body"))
	}
	if len(body.Messages) < 1 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.messages", body.Messages, len(body.Messages), 1, true))
	}
	if len(body.Messages) > 60 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.messages", body.Messages, len(body.Messages), 60, false))
	}
	for _, e := range body.Messages {
		if e != nil {
			if err2 := validateAssistantMessageRequestBody(e, "body.messages[*]"); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	if len(body.Tools) > 40 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.tools", body.Tools, len(body.Tools), 40, false))
	}
	for _, e := range body.Tools {
		if e != nil {
			if err2 := validateAssistantToolRequestBody(e, "body.tools[*]"); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

// ValidateAgentRequestBody runs the validations defined on AgentRequestBody
