// ValidateAssistantMessageRequestBody runs the validations defined on
// AssistantMessage
func ValidateAssistantMessageRequestBody(body *AssistantMessageRequestBody) (err error) {
	if body.Role == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("role", "body"))
	}
	if body.Content == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("content", "body"))
	}
	if body.Role != nil {
		if !(*body.Role == "system" || *body.Role == "user" || *body.Role == "assistant" || *body.Role == "tool") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.role", *body.Role, []any{"system", "user", "assistant", "tool"}))
		}
	}
	if body.Content != nil {
		if utf8.RuneCountInString(*body.Content) > 8000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.content", *body.Content, utf8.RuneCountInString(*body.Content), 8000, false))
		}
	}
	if body.ToolCallID != nil {
		if utf8.RuneCountInString(*body.ToolCallID) > 120 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.toolCallId", *body.ToolCallID, utf8.RuneCountInString(*body.ToolCallID), 120, false))
		}
	}
	if len(body.ToolCalls) > 10 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.toolCalls", body.ToolCalls, len(body.ToolCalls), 10, false))
	}
	for _, e := range body.ToolCalls {
		if e != nil {
			if err2 := validateAssistantToolCallRequestBody(e, "body.toolCalls[*]"); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	return
}

